  "protocol-schema": "1.0.0",
  "metadata": {
    "protocol-name": "Simple Buffer Transfer",
    "author": "Lab Team A",
    "description": "A simple protocol to transfer buffer between two 96-well plates.",
    "created": 1672531200,
    "last-modified": 1672534800,
    "category": "Basic Pipetting",
    "subcategory": "Buffer Prep",
    "tags": [
      "buffer",
      "transfer",
      "96-well"
    ]
  },
  "default-values": {
    "aspirate-flow-rate": {
      "p300_single": 10.0,
      "p1000_single": 15.0
    },
    "dispense-flow-rate": {
      "p300_single": 10.0,
      "p1000_single": 15.0
    },
    "aspirate-mm-from-bottom": 2.0,
    "dispense-mm-from-bottom": 2.0,
    "touch-tip-mm-from-top": 5.0
  },
  "robot": {
    "model": "OT-2 Standard"
  },
  "pipettes": {
    "pipette_1": {
      "mount": "left",
      "name": "p300_single",
      "model": "p300_single_v1.3"
    },
    "pipette_2": {
      "mount": "right",
      "name": "p1000_single",
      "model": "p1000_single_v1.3"
    }
  },
  "labware": {
    "plate_1": {
      "slot": "3",
      "model": "96-flat",
      "display-name": "Source Plate"
    },
    "plate_2": {
      "slot": "8",
      "model": "96-flat",
      "display-name": "Destination Plate"
    }
  },
  "procedure": [
    {
      "subprocedure": [
        {
          "command": "pick-up-tip",
          "params": {
            "pipette": "pipette_1",
            "labware": "plate_1",
            "well": "A1"
          }
        },
        {
          "command": "aspirate",
          "params": {
            "flow-rate": {
              "flow-rate": 12.0
            },
            "pipette": "pipette_1",
            "labware": "plate_1",
            "well": "A1",
            "volume": 50.0,
            "offsetFromBottomMm": {
              "offsetFromBottomMm": 2.5
            }
          }
        },
        {
          "command": "touch-tip",
          "params": {
            "pipette": "pipette_1",
            "labware": "plate_2",
            "well": "A1",
            "offsetFromBottomMm": {
              "offsetFromBottomMm": 5.0
            }
          }
        },
        {
          "command": "dispense",
          "params": {
            "flow-rate": {
              "flow-rate": 12.0
            },
            "pipette": "pipette_1",
            "labware": "plate_2",
            "well": "A1",
            "volume": 50.0,
            "offsetFromBottomMm": {
              "offsetFromBottomMm": 2.5
            }
          }
        },
        {
          "command": "drop-tip",
          "params": {
            "pipette": "pipette_1",
            "labware": "plate_2",
            "well": "A1"
          }
        },
        {
          "command": "delay",
          "params": {
            "wait": 1.5,
            "message": "Waiting for settling"
          }
        }
      ],
      "annotation": {
        "name": "Transfer Step 1",
        "description": "Transfer 50uL from A1 of source to A1 of destination."
      }
    }
  ]
