[
  {
    "name": "Auto-remediation Ruleset",
    "hosts": "web_servers",
    "gather_facts": true,
    "match_multiple_rules": true,
    "execution_strategy": "parallel",
    "default_events_ttl": "10 minutes",
    "sources": [
      {
        "name": "Prometheus_Alerts",
        "filters": [
          {
            "severity": "critical"
          }
        ]
      }
    ],
    "rules": [
      {
        "name": "High_CPU_Usage",
        "enabled": true,
        "throttle": {
          "once_within": "5 minutes",
          "group_by_attributes": [
            "host",
            "service"
          ]
        },
        "condition": {
          "any": [
            "cpu_usage > 90",
            "memory_usage > 85"
          ]
        },
        "actions": [
          {
            "run_module": {
              "name": "ansible.builtin.service",
              "post_events": true,
              "set_facts": true,
              "verbosity": 1,
              "module_args": {
                "name": "nginx",
                "state": "restarted"
              },
              "extra_vars": {
                "reason": "High CPU detected"
              }
            }
          },
          {
            "set_fact": {
              "fact": {
                "remediation_status": "completed"
              }
            }
          }
        ]
      },
      {
        "name": "Disk_Space_Warning",
        "enabled": true,
        "condition": {
          "not_all": {
            "not_all": [
              "disk_free_gb > 10"
            ],
            "timeout": "30 seconds"
          }
        },
        "action": {
          "run_playbook": {
            "name": "cleanup_temp_files.yml",
            "copy_files": false,
            "post_events": true,
            "set_facts": true,
            "verbosity": 0,
            "retry": true,
            "retries": 3,
            "delay": 5,
            "extra_vars": {
              "target_path": "/tmp"
            }
          }
        }
      }
    ]
  }
