    "labels": {
      "app": "web-server",
      "env": "prod"
    },
    "annotations": {
      "description": "Main production deployment"
    }
  },
  "commonAnnotations": {
    "managed-by": "kustomize"
  },
  "commonLabels": {
    "team": "backend"
  },
  "resources": [
    "deployment.yaml",
    "service.yaml"
  ],
  "namePrefix": "prod-",
  "namespace": "production",
  "generatorOptions": {
    "disableNameSuffixHash": true,
    "immutable": true,
    "labels": {
      "generated": "true"
    }
  },
  "configMapGenerator": [
    {
      "name": "app-config",
      "literals": [
