      "vars": {
        "app_port": 8080,
        "environment_name": "production"
      },
      "tasks": [
        {
          "name": "Install Nginx",
          "action": "ansible.builtin.apt",
          "args": {
            "name": "nginx",
            "state": "present"
          },
          "become": true,
          "become_method": "sudo",
          "tags": [
            "install",
            "web"
          ]
        },
        {
          "name": "Configure Firewall",
          "action": "ansible.builtin.ufw",
          "args": {
            "rule": "allow",
            "port": "80"
          },
          "become": true,
          "tags": [
            "security"
          ]
        },
        {
          "block": [
            {
              "name": "Update Config",
              "action": "ansible.builtin.template",
              "args": {
                "src": "nginx.conf.j2",
                "dest": "/etc/nginx/nginx.conf"
              }
            },
            {
              "name": "Restart Nginx",
              "action": "ansible.builtin.service",
              "args": {
                "name": "nginx",
                "state": "restarted"
              }
            }
          ],
          "name": "Configuration Block",
          "any_errors_fatal": true
        }
      ],
      "vars_files": [
        "common_vars.yml"
      ],
      "remote_user": "admin"
    }
  ]
