{
  "title": "KoDE/CI Build Spec",
  "on": {
    "push": {
      "branches": [
        "main",
        "develop"
      ],
      "tags": [
        "v*.*.*"
      ],
      "commit": {
        "message-contain": "[RELEASE]"
      }
    },
    "pull-request": {
      "branches": [
        "main"
      ],
      "types": [
        "opened",
        "synchronize"
      ],
      "commit": {
        "message-contain": "fix:"
      }
    }
  },
  "jobs": [
    {
      "name": "Build_And_Test",
      "execute": [
        "npm install",
        "npm run build",
        "npm test"
      ],
      "set-proxy": [
        "npm"
      ],
      "no-proxy-hosts": [
        "localhost",
        "127.0.0.1"
      ],
      "run-on": {
        "image": "+@basebox:latest",
        "resources": {
          "cpu": "2.0",
          "memory": "4Gi"
        },
        "use": [
          "docker"
        ],
        "platform": "k8s"
      },
      "artifacts": [
        "dist/",
        "build.log"
      ],
      "caches": [
        {
          "key": "node_modules_cache",
          "path": "node_modules"
        }
      ],
      "max-execution-time": "30m",
      "post-process": {
        "git-ops": {
          "manifest": {
            "repo": "my-org/manifest-repo",
            "branch": "main"
          },
          "update": [
            "kubectl apply -f ./manifests"
          ],
          "with-artifacts": [
            "dist/index.html"
          ]
        }
      }
    },
    {
      "name": "Release_Android",
      "execute": [
        "./gradlew assembleRelease"
      ],
      "run-on": {
        "image": "+@android-builder",
        "resources": "large",
        "use": [
          "docker",
          "mobil-keystore"
        ],
        "platform": "k8s"
      },
      "artifacts": [
        "app/build/outputs/apk"
      ],
      "post-process": {
        "app-center-release": {
          "app-id": "com.example.app",
          "release-group-tag": "production-v1",
          "testers": [
            "@john_doe",
            "@@qa_team",
            "corp@@internal_testers"
          ]
        }
      }
    }
  ],
  "environment": [
    {
      "name": "NODE_ENV",
      "value": "production",
      "branch": "main"
    },
    {
      "name": "API_KEY",
      "value": "secret_key_12345",
      "branch": "develop"
    }
  ]
}

